def totalNumbers(digits: List[int]) -> int:
    distinct_numbers = set()
    for p in set(permutations(digits, 3)):
        if p[0] != 0 and p[2] % 2 == 0:
            distinct_numbers.add(p)
    return len(distinct_numbers)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    max_by_deck = n * n
    max_by_weight = maxWeight // w
    return min(max_by_deck, max_by_weight)

def reverseDegree(s: str) -> int:
    total = 0
    for index, char in enumerate(s):
        reversed_alphabet_value = 26 - (ord(char) - ord('a'))
        total += (index + 1) * reversed_alphabet_value
    return total

