def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    # Create a dp array to store the maximum length of subsequence ending at each index
    dp = [1] * n
    # Iterate through the array to find the longest subsequence
    for i in range(n):
        for j in range(i + 1, n):
            if abs(nums[j] - nums[j - 1]) <= abs(nums[i] - nums[i - 1]) if i > 0 else True:
                dp[j] = max(dp[j], dp[i] + 1)
    return max(dp)

