def maxFrequency(nums: List[int], k: int) -> int:
    # Frequency map to count occurrences of each number
    freq = [0] * 51  # Since 1 <= nums[i], k <= 50
    for num in nums:
        freq[num] += 1

    initial_freq = freq[k]  # Initial frequency of k
    max_gain = 0

    # Now we need to find the best value to convert to k
    for v in range(1, 51):  # Check all possible values from 1 to 50
        if v == k:
            continue
        if freq[v] > 0:
            # Calculate gain using a sliding window approach
            gain = [0] * len(nums)
            for i in range(len(nums)):
                if nums[i] == v:
                    gain[i] = 1  # Gain for converting v to k
                elif nums[i] == k:
                    gain[i] = -1  # Loss for converting k to k

            # Find maximum subarray sum using Kadane's algorithm
            current_sum = 0
            for g in gain:
                current_sum += g
                if current_sum < 0:
                    current_sum = 0
                max_gain = max(max_gain, current_sum)

    return initial_freq + max_gain

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_dist = 0

    for i, char in enumerate(s):
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1

        # Calculate the current Manhattan distance
        current_dist = abs(x) + abs(y)
        # Update max distance considering how many changes we can make
        max_dist = max(max_dist, current_dist)

        # Check changes to increase distance
        if k > 0:
            # Consider the maximum possible increase in distance
            reachable_dist = current_dist + min(k, i + 1)
            max_dist = max(max_dist, reachable_dist)

    return max_dist + k
